contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: caller attempts to be jojoTeam or not
    // we model by passing a boolean isTeam; if true, we first set c.jojoTeam via calling from this contract's address
    // But we cannot change msg.sender for c. The test environment deploys C fresh and this contract is the deployer of c.
    // We'll use the following approach: if isTeam==true, we simulate that this contract is the jojoTeam by checking
    // that c.jojoTeam is writable only via direct storage (not possible). Instead, C exposes public jojoTeam variable
    // so when C was deployed in the checker, jojoTeam may be set to some address. We can't change it. Therefore
    // we assert the general rule only in terms of whether calls from this contract (msg.sender = address(this)) succeed
    // or revert: if address(this) equals c.jojoTeam then the call must succeed and produce a NewEmergencyOracle event
    // and the created EmergencyOracle must have owner == address(this) and description == provided string.

    // Because we cannot observe events, we instead observe effects via C's public surface: newEmergencyOracle creates
    // a new EmergencyOracle contract but C does not store it publicly; however the emitted event isn't observable. But
    // we can check behavior by attempting to call getAssetPrice() on the created oracle only if we had its address — we don't.
    // To remain within constraints, we instead assert a safer general rule: calling newEmergencyOracle reverts iff address(this) != c.jojoTeam.
    // Additionally, when it does not revert, the call must succeed (non-revert). This is a general property about caller authorization.

    // The single public function below takes an arbitrary description and a boolean flag isTeamGuess (not used to modify c).
    // It calls newEmergencyOracle and records whether it reverted. The assert states the authorization equivalence: the call
    // succeeds exactly when c.jojoTeam equals address(this).

    function run(string calldata description, bool isTeamGuess) public payable {
        require(true);

        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the public jojoTeam value
        address jt = c.jojoTeam();

        // General rule: the call reverts iff caller is not jojoTeam
        assert(reverted == (jt != address(this)));
    }

    receive() external payable {}
}

