contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Single public function driving the test
    function run(string calldata description) public payable {
        require(true);

        // Call newEmergencyOracle and capture whether it reverted
        bool reverted;
        address createdOracle = address(0);
        // We cannot catch events directly; but when successful the call returns (no revert)
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call did not revert, then a NewEmergencyOracle event must have been emitted
        // and the newly created EmergencyOracle should be observable via its owner() and description() public getters.
        // We can't read emitted events here, but we can reason: when not reverted, the function created a new EmergencyOracle
        // whose owner() equals msg.sender in its constructor (transferOwnership(msg.sender)) and description equals input.
        // Since our test contract is the caller, the owner should be address(this).
        // We attempt to discover the created oracle address by scanning the balance of c: not possible.
        // However, C emits NewEmergencyOracle(sender, newOracle) and the only observable effect we can query is that
        // any created EmergencyOracle at an address would have owner()==address(this) and description()==description.
        // To check this without event data, we conservatively assert: if the call succeeded then there exists an address a
        // (we quantify by using the address returned by calling c.jojoTeam() — but that's unrelated). Solidity tests can't quantify existentials,
        // so we re-express to a universally checkable condition: when the call succeeds, msg.sender (address(this)) must be equal to c.jojoTeam()
        // OR the call must revert. This avoids relying on event observation while still encoding that only the jojoTeam may create oracles.
        // Therefore we assert that (not reverted) implies (c.jojoTeam() == address(this)).

        address jt = c.jojoTeam();
        assert(!reverted ? jt == address(this) : true);
    }

    receive() external payable {}
}
